<script setup>
import { formatDateTime, formatDate } from "../utils/workflow.js"
import { computed, onMounted, ref } from 'vue'
import { apiGet } from '../services/api.js'
import { useAuthStore, roles } from '../stores/auth.js'
import { label, today } from '../utils.js'
import TrendChart from '../components/TrendChart.vue'
import AppIcon from '../components/AppIcon.vue'
import { normalizeSearch } from '../utils/workflow.js'
const patientSearch = ref('')
const patientMatches = computed(() => patientSearch.value.trim() ? (data.value?.patients || []).filter(p => normalizeSearch(p.name).includes(normalizeSearch(patientSearch.value))).slice(0, 5) : [])
const auth = useAuthStore(), data = ref(null), error = ref(''), busy = ref(false), selected = ref('')
const filter = ref({ from: today().slice(0, 7) + '-01', to: today(), patient_id: '' })
const clinical = computed(() => ['doctor', 'nurse'].includes(auth.user?.role))
const metricLabels = { patients: 'Pacientes vinculados', appointments_today: 'Minhas consultas hoje', active_plans: 'Planos ativos', goals_tracked: 'Metas acompanhadas', measurements: 'Medições no período', reviews_completed: 'Reavaliações concluídas', goals_attained: 'Metas atingidas', actions_completed: 'Ações pactuadas realizadas', plans_revised: 'Planos revisados', reassessments_due: 'Reavaliações previstas' }
const indicator = computed(() => data.value?.indicators?.find(i => Number(i.id) === Number(selected.value)))
async function load() {
  busy.value = true; error.value = ''
  try {
    if (auth.user?.role === 'navigator') { data.value = null; return }
    const path = clinical.value ? (auth.user?.role === 'nurse' ? '/nursing/dashboard' : '/clinical/dashboard') : '/portal'
    data.value = await apiGet(path + '?' + new URLSearchParams(filter.value))
    if (!data.value.indicators?.some(i => Number(i.id) === Number(selected.value))) selected.value = data.value.indicators?.[0]?.id || ''
  } catch (e) { data.value = null; error.value = e.message } finally { busy.value = false }
}
onMounted(load)
</script>
<template>

  <div class="d-flex justify-content-between align-items-start flex-wrap gap-3 mb-4"><div><p class="eyebrow">VISÃO DO CUIDADO</p><h1>{{ auth.user?.role === 'nurse' ? 'Acompanhamento de enfermagem' : auth.user?.role === 'doctor' ? 'Gestão clínica' : 'Meu espaço' }}</h1><p class="text-secondary">{{ roles[auth.user?.role] }} · {{ auth.user?.name }}</p></div><RouterLink v-if="clinical" to="/patients" class="btn btn-success">Acompanhar pacientes →</RouterLink></div>
  <p v-if="auth.user?.role === 'navigator'">Acesse o <RouterLink to="/continuity">ELO Reconecta</RouterLink> para acolhimentos e retornos.</p>
  <section v-if="['worker', 'dependent'].includes(auth.user?.role)" class="row g-4 mb-4"><div class="col-lg-7"><div class="card card-body h-100"><p class="eyebrow">SEU PRÓXIMO PASSO</p><h2 class="h3">Cuidar de você também cabe na rotina</h2><p>Escolha atendimento perto de casa, da indústria ou por teleconsulta. Você pode pedir apoio para organizar seus retornos.</p><RouterLink to="/find-care" class="btn btn-success align-self-start">Encontrar atendimento →</RouterLink></div></div><div class="col-lg-5"><div class="card card-body h-100"><h2 class="h4">Meu cuidado</h2><p>Conteúdos rápidos, orientações de uso e campanhas por ciclos, no seu ritmo.</p><RouterLink to="/my-care" class="btn btn-outline-success align-self-start">Conhecer conteúdos e campanhas →</RouterLink></div></div></section>
  <section v-if="auth.user?.management_level && auth.user.management_level !== 'none'" class="card card-body mb-4"><h2 class="h5">Gestão da operação</h2><p>Indústrias, contratos, elegibilidade, equipes e campanhas, com permissões próprias.</p><div class="d-flex flex-wrap gap-3"><RouterLink to="/management">Abrir gestão →</RouterLink><RouterLink to="/campaign-management">Campanhas por ciclos →</RouterLink></div></section>
  <section v-if="clinical || auth.user?.role === 'navigator'" class="d-flex flex-wrap gap-3 mb-4"><RouterLink v-if="clinical" to="/my-agenda">Minha agenda presencial e teleconsulta →</RouterLink><RouterLink to="/engagement">Fila de acolhimento e campanhas →</RouterLink><RouterLink v-if="clinical" to="/education-editor">Revisar conteúdos educativos →</RouterLink></section>
  <section v-if="clinical" class="card card-body mb-4"><label for="clinical-patient-search" class="form-label">Qual paciente você vai acompanhar?</label><div class="search-field" style="max-width: none"><AppIcon name="search" /><input id="clinical-patient-search" v-model="patientSearch" class="form-control" type="search" placeholder="Digite o nome para abrir direto o acompanhamento"></div><div v-if="patientSearch.trim()" class="mt-2"><div v-for="p in patientMatches" :key="p.id" class="list-entry"><strong>{{ p.name }}</strong><div class="d-flex gap-2 ms-auto"><RouterLink :to="`/patients/${p.id}?section=records`" class="btn btn-sm btn-success">Registrar evolução</RouterLink><RouterLink :to="`/patients/${p.id}?section=indicators`" class="btn btn-sm btn-outline-success">Medição</RouterLink></div></div><p v-if="!patientMatches.length" class="small text-secondary mt-3 mb-0">Nenhum paciente vinculado com esse nome.</p></div></section>
  <form v-if="clinical" class="card card-body mb-4" @submit.prevent="load"><div class="row align-items-end g-3"><div class="col-md-4"><label for="from" class="form-label">De</label><input id="from" v-model="filter.from" type="date" class="form-control" required></div><div class="col-md-4"><label for="to" class="form-label">Até</label><input id="to" v-model="filter.to" type="date" class="form-control" required></div><div class="col-md-4"><button class="btn btn-outline-success" :disabled="busy">Aplicar período</button></div></div></form>
  <p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="busy" role="status">Carregando…</p>
  <template v-if="data && clinical">
    <div class="row g-3 mb-4"><div v-for="(value, key) in data.metrics" :key="key" class="col-6 col-lg-3"><div class="card metric-card h-100"><div class="card-body"><p class="text-secondary small mb-2">{{ metricLabels[key] }}</p><strong class="display-6">{{ value }}</strong></div></div></div></div>
    <div class="row g-4"><section class="col-lg-8"><div class="card card-body h-100"><h2 class="h5">Evolução dos indicadores</h2><label for="chart-indicator" class="form-label">Indicador</label><select id="chart-indicator" v-model="selected" class="form-select mb-3"><option value="">Selecione</option><option v-for="i in data.indicators" :key="i.id" :value="i.id">{{ i.name }} · paciente #{{ i.patient_id }} · {{ i.unit }}</option></select><TrendChart v-if="indicator" :indicator="indicator" :measurements="data.measurements" /><p v-else class="text-secondary">Nenhum indicador selecionado. Cadastre indicadores no espaço do paciente.</p><p class="small text-secondary mt-3 mb-0">Origens exibidas separadamente. O gráfico não gera diagnóstico ou conduta.</p></div></section><section class="col-lg-4"><div class="card card-body h-100"><h2 class="h5">Reavaliações e continuidade</h2><p v-if="!data.plans.length" class="text-secondary">Nenhum plano neste acompanhamento.</p><div v-for="p in data.plans.filter(p => p.status !== 'closed')" :key="p.id" class="border-bottom py-3"><RouterLink :to="`/patients/${p.patient_id}?plan=${p.id}`">{{ p.patient_name }}</RouterLink><div class="small text-secondary">Reavaliar em {{ formatDate(p.reassessment_date) }} · {{ label(p.status) }}</div></div><RouterLink class="mt-3" to="/continuity">Consultar pendências de retorno →</RouterLink></div></section></div>
    <section class="card card-body mt-4"><h2 class="h5">Consultas e retornos no período</h2><div class="table-responsive"><table class="table"><thead><tr><th>Paciente</th><th>Data e hora</th><th>Situação</th></tr></thead><tbody><tr v-for="a in data.appointments" :key="a.id"><td><RouterLink :to="`/patients/${a.patient_id}`">{{ a.patient_name }}</RouterLink></td><td>{{ formatDateTime(a.scheduled_at) }}</td><td>{{ label(a.status) }}</td></tr><tr v-if="!data.appointments.length"><td colspan="3">Nenhum atendimento no período.</td></tr></tbody></table></div></section>
    <section class="card card-body mt-4"><h2 class="h5">Encaminhamentos solicitados</h2><p v-if="!data.referrals.length">Nenhuma solicitação.</p><div v-for="r in data.referrals" :key="r.id" class="border-bottom py-2">Paciente #{{ r.patient_id }} → {{ r.recipient_name }}<p class="mb-0">{{ r.reason }}</p><small>{{ formatDateTime(r.created_at) }}</small></div></section>
    <section v-if="auth.user?.role === 'nurse'" class="card card-body mt-4"><h2 class="h5">Enfermagem · evoluções e ações educativas</h2><p v-if="!data.evolutions.length">Nenhum registro no período.</p><div v-for="e in data.evolutions" :key="e.id" class="border-bottom py-2"><strong>{{ label(e.kind) }}</strong> · {{ formatDateTime(e.created_at) }}<p>{{ e.notes }}</p></div><h3 class="h6 mt-3">Solicitações de acolhimento e revisão pela APS</h3><p v-if="!data.notifications.length">Nenhum aviso no período.</p><p v-for="n in data.notifications" :key="n.id">Paciente #{{ n.patient_id }} · {{ label(n.event_type) }} · {{ formatDateTime(n.created_at) }}</p></section>
  </template>
  <template v-else-if="data"><p v-if="data.suppressed" class="alert alert-info">{{ data.message }}</p><div v-if="data.participants" class="card card-body"><h2 class="h5">Visão agregada da empresa</h2><p>{{ data.participants }} participantes</p><p v-for="a in data.appointment_totals" :key="a.status">{{ label(a.status) }}: {{ a.n ?? 'Suprimido (grupo pequeno)' }}</p></div><div v-if="data.appointments" class="card card-body"><h2 class="h5">Meus retornos</h2><p v-if="!data.appointments.length">Nenhum retorno previsto.</p><p v-for="a in data.appointments" :key="a.id">{{ formatDateTime(a.scheduled_at) }} · {{ label(a.status) }}</p></div></template>
</template>
